mapper.select:
SELECT * FROM discovery_title
WHERE origin = #{origin} AND (resolved_at IS NULL OR resolved_at < #{staleBefore})
AND title_key > #{afterKey}
ORDER BY title_key LIMIT #{size}

mapper.update:
UPDATE discovery_title SET resolved_issns = #{issns, typeHandler=org.catalogueoflife.nametracker.store.type.StringArrayTypeHandler, jdbcType=ARRAY},
  resolved_at = #{at}
WHERE origin = #{origin} AND title_key = #{titleKey}
